import { API_BASE_URL } from './config.js';

// 取得目前選擇帳號資訊（含 simulation_date）
async function getCurrentAccount() {
	try {
		const res = await fetch(`${API_BASE_URL}/current-account`, { credentials: 'include' });
		if (!res.ok) return null;
		const data = await res.json();
		if (!data.ok) return null;
		return data.account;
	} catch (e) {
		return null;
	}
}

async function fetchProfitLoss(accountId, simulationDate = null) {
	let url = `${API_BASE_URL}/profit_loss?account_id=${accountId}`;
	if (simulationDate) {
		url += `&simulation_date=${simulationDate}`;
	}
	try {
		const res = await fetch(url);
		if (!res.ok) throw new Error('API 請求失敗');
		const data = await res.json();
		return data;
	} catch (err) {
		console.error('損益查詢失敗:', err);
		return null;
	}
}

function renderProfitLoss(data) {
	if (!data) return;
	const simDate = window.simulationDate || null;
	// 動態插入查詢日期欄位
	const unrealizedTable = document.querySelectorAll('table')[0];
	const realizedTable = document.querySelectorAll('table')[1];
	const unrealizedTheadTr = unrealizedTable.querySelector('thead tr');
	const realizedTheadTr = realizedTable.querySelector('thead tr');
	// 只在 simulationDate 有值時插入欄位
	if (simDate) {
		if (!unrealizedTheadTr.querySelector('.sim-date-th')) {
			const th = document.createElement('th');
			th.textContent = '查詢日期';
			th.className = 'sim-date-th';
			unrealizedTheadTr.insertBefore(th, unrealizedTheadTr.firstChild);
		}
		if (!realizedTheadTr.querySelector('.sim-date-th')) {
			const th = document.createElement('th');
			th.textContent = '查詢日期';
			th.className = 'sim-date-th';
			realizedTheadTr.insertBefore(th, realizedTheadTr.firstChild);
		}
	} else {
		// 若 simulationDate 無值則移除欄位
		const th1 = unrealizedTheadTr.querySelector('.sim-date-th');
		if (th1) th1.remove();
		const th2 = realizedTheadTr.querySelector('.sim-date-th');
		if (th2) th2.remove();
	}
	// 未實現損益表格
	const unrealizedTbody = unrealizedTable.querySelector('tbody');
	unrealizedTbody.innerHTML = '';
	if (Array.isArray(data.holdings)) {
		data.holdings.forEach(h => {
			const tr = document.createElement('tr');
			let row = '';
			if (simDate) row += `<td>${simDate}</td>`;
			// 判斷現價
			const curPrice = (h.current_price === undefined || h.current_price === null) ? '-' : h.current_price;
			const curValue = (h.current_price === undefined || h.current_price === null) ? '-' : (h.current_price * h.quantity);
			const unrealizedProfit = (h.current_price === undefined || h.current_price === null) ? '-' : h.unrealized_profit;
			let profitRate = '-';
			if (h.current_price !== undefined && h.current_price !== null && h.purchase_price && h.quantity) {
				const cost = h.purchase_price * h.quantity;
				if (cost !== 0) {
					profitRate = ((h.unrealized_profit / cost) * 100).toFixed(2) + '%';
				}
			}
			row += `
				<td>${h.symbol}</td>
				<td>${h.name}</td>
				<td>-</td>
				<td>-</td>
				<td>${h.quantity}</td>
				<td>${h.purchase_price} / ${curPrice}</td>
				<td>${h.purchase_price * h.quantity} / ${curValue}</td>
				<td class="${unrealizedProfit !== '-' && unrealizedProfit >= 0 ? 'text-success' : 'text-danger'}">${unrealizedProfit}</td>
				<td>${profitRate}</td>
				<td><a href="#" class="btn btn-sm btn-primary btn-close-position">平倉</a></td>
			`;
			tr.innerHTML = row;
			unrealizedTbody.appendChild(tr);
		});
	}
	// 已實現損益表格
	// 修改已實現損益表格的 thead，只保留「總計」和金額
	const realizedThead = realizedTable.querySelector('thead');
	realizedThead.innerHTML = '';
	const realizedTr = document.createElement('tr');
	if (simDate) {
		realizedTr.innerHTML = `<th>查詢日期</th><th>總計</th><th>金額</th>`;
	} else {
		realizedTr.innerHTML = `<th>總計</th><th>金額</th>`;
	}
	realizedThead.appendChild(realizedTr);

	// 只渲染一行總計金額
	const realizedTbody = realizedTable.querySelector('tbody');
	realizedTbody.innerHTML = '';
	const tr = document.createElement('tr');
	let row = '';
	if (simDate) row += `<td>${simDate}</td>`;
	row += `<td>總計</td><td class="${data.realized_profit >= 0 ? 'text-success' : 'text-danger'}">${data.realized_profit}</td>`;
	tr.innerHTML = row;
	realizedTbody.appendChild(tr);
}

window.addEventListener('DOMContentLoaded', async () => {
    const account = await getCurrentAccount();
    if (!account) return;
    const accountId = account.selected_account_id || account.saccount_id || account.id;
    const simulationDate = account.selected_account_simulation_date || account.simulation_date || null;
    const data = await fetchProfitLoss(accountId, simulationDate);
    renderProfitLoss(data);
});
